"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { TrainFront, Loader2, ArrowRight } from "lucide-react";
import axios from "axios";
import { API_BASE } from "@/lib/api";

import { GoogleAuthButton } from "@/components/GoogleAuthButton";
import { getAndClearReturnUrl, saveReturnUrl } from "@/lib/returnUrl";

export default function LoginPage() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [referralCode, setReferralCode] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isBlocked, setIsBlocked] = useState(false);

  const [returnUrl, setReturnUrl] = useState<string | null>(null);

  useEffect(() => {
    if (typeof window !== 'undefined') {
      const params = new URLSearchParams(window.location.search);
      if (params.get('blocked') === 'true') {
        setIsBlocked(true);
      }
      const ret = params.get('returnUrl');
      if (ret) {
        setReturnUrl(ret);
        saveReturnUrl(ret);
      }
      // On login page entry, purge dead tokens if user is not logged in so stale tokens don't poison auth
      try {
        const storedUser = localStorage.getItem('user');
        if (!storedUser || storedUser === 'undefined' || storedUser === 'null') {
          localStorage.removeItem('accessToken');
          localStorage.removeItem('refreshToken');
        }
      } catch {}
    }
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      // Proactively clear stale tokens before authenticating
      try {
        localStorage.removeItem('accessToken');
        localStorage.removeItem('refreshToken');
      } catch {}

      // PHASE_5B142 Fix: withCredentials:true so the browser stores the
      // refreshToken httpOnly cookie from the response. Without this flag
      // the browser discards Set-Cookie on cross-origin requests, leaving
      // the cookie unset and forcing the fallback refresh path.
      const res = await axios.post(`${API_BASE}/auth/login`, {
        email: email.trim().toLowerCase(),
        password: password.trim(),
        referralCode: referralCode.trim()
      }, { withCredentials: true });
      if (res.data.success) {
        // ✅ API returns { success: true, data: user } — store res.data.data
        if (res.data?.data) {
          const userData = res.data.data;
          const isVerified = userData.mobileVerified === true || userData.mobileVerification?.verified === true;
          const unifiedUser = {
            ...userData,
            mobileVerified: isVerified,
            mobileVerification: {
              ...(userData.mobileVerification || {}),
              verified: isVerified,
              method: userData.mobileVerification?.method || userData.mobileVerificationMethod || "WHATSAPP"
            }
          };
          localStorage.setItem("user", JSON.stringify(unifiedUser));
        }
        if (res.data.accessToken) {
          localStorage.setItem("accessToken", res.data.accessToken);
        }
        // Store refreshToken for cross-domain (.com/.online) cookie fallback
        if (res.data.refreshToken) {
          localStorage.setItem("refreshToken", res.data.refreshToken);
        }

        if (res.data.requireMobileVerification) {
          window.location.href = res.data.onboardingUrl || '/onboarding/verify-mobile';
          return;
        }

        const targetUrl = getAndClearReturnUrl();
        window.location.href = targetUrl;
      }
    } catch (err: any) {
      const code = err.response?.data?.code;
      if (code === 'USER_NOT_FOUND') {
        setError("Account not found. Please check your email or create a new account.");
      } else {
        // Generic message for wrong password, blocked account, etc.
        // Do NOT reveal whether the account exists to prevent enumeration.
        setError(err.response?.data?.error || "Login failed. Please check your credentials and try again.");
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="w-full flex-1 flex flex-col p-4 md:p-8 items-center justify-center selection:bg-rose-500/30">
      <div className="w-full max-w-md bg-card border border-subtle rounded-3xl p-8 shadow-2xl backdrop-blur-xl">
        <div className="flex flex-col items-center mb-8">
          <div className="p-3 bg-blue-500/10 border border-blue-500/20 rounded-xl mb-4">
            <TrainFront className="w-8 h-8 text-blue-600 dark:text-blue-400" />
          </div>
          <h1 className="text-2xl font-bold tracking-tight text-main">Welcome Back</h1>
          <p className="text-sm text-muted mt-1">Login to access premium Trayago features</p>
          <div className="mt-3 px-4 py-2 bg-blue-500/5 border border-blue-500/10 rounded-xl text-center w-full">
            <p className="text-xs text-blue-600 dark:text-blue-400 font-medium tracking-wide">
              🚄 India&apos;s AI-powered split journey planner
            </p>
            <p className="text-[11px] text-muted mt-0.5">
              Find confirmed seats when direct trains are waitlisted
            </p>
          </div>
          <div className="mt-3 p-3 bg-emerald-500/10 border border-emerald-500/20 rounded-xl text-center w-full">
            <p className="text-xs font-semibold text-emerald-600 dark:text-emerald-400">
              🎁 New users receive 30 minutes of AI Split Journey access free.
            </p>
          </div>
        </div>

        {isBlocked && (
          <div className="mb-6 p-4 rounded-xl bg-red-500/10 border border-red-500/20 text-red-500 dark:text-red-400 text-sm text-center font-medium">
            Your account has been suspended by an administrator. Please contact support.
          </div>
        )}

        <form onSubmit={handleLogin} className="space-y-4">
          <div>
            <label className="text-xs font-semibold text-muted uppercase tracking-wider pl-1">Email</label>
            <input
              type="email"
              value={email}
              onChange={e => setEmail(e.target.value)}
              aria-invalid={!!error}
              aria-describedby={error ? "login-error-msg" : undefined}
              className="w-full mt-1 bg-input border border-subtle rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500 transition-all text-main"
              placeholder="you@example.com"
              required
            />
          </div>

          <div>
            <label className="text-xs font-semibold text-muted uppercase tracking-wider pl-1">Password</label>
            <input
              type="password"
              value={password}
              onChange={e => setPassword(e.target.value)}
              aria-invalid={!!error}
              aria-describedby={error ? "login-error-msg" : undefined}
              className="w-full mt-1 bg-input border border-subtle rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500 transition-all text-main"
              placeholder="••••••••"
              required
            />
            <div className="flex justify-end mt-2">
              <Link href="/forgot-password" className="text-xs text-blue-600 dark:text-blue-400 hover:text-blue-700 dark:hover:text-blue-300 hover:underline transition-colors">Forgot Password?</Link>
            </div>
          </div>

          <div>
            <label className="text-xs font-semibold text-muted uppercase tracking-wider pl-1">Referral Code <span className="normal-case">(optional)</span></label>
            <input
              type="text"
              value={referralCode}
              onChange={e => setReferralCode(e.target.value.toUpperCase())}
              className="w-full mt-1 bg-input border border-subtle rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500 transition-all text-main uppercase font-mono tracking-widest"
              placeholder="e.g. RAIL-1234"
            />
          </div>

          {error && <div id="login-error-msg" role="alert" className="text-sm text-red-500 bg-red-500/10 p-3 rounded-xl border border-red-500/20">{error}</div>}

          <button
            type="submit"
            disabled={loading}
            className="w-full py-3 mt-4 bg-blue-600 hover:bg-blue-700 hover:-translate-y-0.5 hover:shadow-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500/50 text-white font-bold rounded-xl flex items-center justify-center gap-2 transition-all shadow-md active:scale-95"
          >
            {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : <>Login <ArrowRight className="w-4 h-4" /></>}
          </button>
        </form>

        <div className="relative mt-6 mb-4">
          <div className="absolute inset-0 flex items-center">
            <div className="w-full border-t border-subtle"></div>
          </div>
          <div className="relative flex justify-center text-sm">
            <span className="px-2 bg-card text-muted">Or continue with</span>
          </div>
        </div>

        <GoogleAuthButton 
          referralCode={referralCode} 
          onError={(msg) => setError(msg)} 
        />

        <p className="text-center text-sm text-muted mt-6">
          Don&apos;t have an account?{" "}
          <Link
            href={returnUrl ? `/signup?returnUrl=${encodeURIComponent(returnUrl)}` : "/signup"}
            className="text-blue-600 dark:text-blue-400 hover:underline font-semibold"
          >
            Sign Up
          </Link>
        </p>

        <p className="text-center text-[11px] text-muted/80 mt-4 leading-relaxed">
          By logging in, you agree to Trayago&apos;s{" "}
          <Link href="/terms" className="underline hover:text-main transition-colors">
            Terms of Service
          </Link>{" "}
          and{" "}
          <Link href="/privacy" className="underline hover:text-main transition-colors">
            Privacy Policy
          </Link>.
        </p>
      </div>
    </div>
  );
}
